    "rReadOnlyAdminGroup": {
      "Type": "AWS::IAM::Group",
      "Properties": {
        "Path": "/"
      }
    },

    "rReadOnlyAdminRole": {
      "Type": "AWS::IAM::Role",
      "Properties": {
        "AssumeRolePolicyDocument": {
          "Statement": [{
            "Effect": "Allow",
            "Principal": {
              "Service": [
                "ec2.amazonaws.com"
              ]

            },
            "Action": [
              "sts:AssumeRole"
            ]
          }]
        }
      }
    },

    "rReadOnlyAdminProfile": {
      "Type": "AWS::IAM::InstanceProfile",
      "DependsOn": "rReadOnlyAdminRole",
      "Properties": {
        "Path": "/",
        "Roles": [{
          "Ref": "rReadOnlyAdminRole"
        }]
      }
    },

    "rReadOnlyAdminPolicy": {
      "Type": "AWS::IAM::ManagedPolicy",
      "DependsOn": "rReadOnlyAdminProfile",
      "Properties": {
        "PolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [{
            "Action": [
              "appstream:Get*",
              "autoscaling:Describe*",
              "cloudformation:DescribeStacks",
              "cloudformation:DescribeStackEvents",
              "cloudformation:DescribeStackResource",
              "cloudformation:DescribeStackResources",
              "cloudformation:GetTemplate",
              "cloudformation:List*",
              "cloudfront:Get*",
              "cloudfront:List*",
              "cloudtrail:DescribeTrails",
              "cloudtrail:GetTrailStatus",
              "cloudwatch:Describe*",
              "cloudwatch:Get*",
              "cloudwatch:List*",
              "directconnect:Describe*",
              "dynamodb:GetItem",
              "dynamodb:BatchGetItem",
              "dynamodb:Query",
              "dynamodb:Scan",
              "dynamodb:DescribeTable",
              "dynamodb:ListTables",
              "ec2:Describe*",
              "elasticache:Describe*",
              "elasticbeanstalk:Check*",
              "elasticbeanstalk:Describe*",
              "elasticbeanstalk:List*",
              "elasticbeanstalk:RequestEnvironmentInfo",
              "elasticbeanstalk:RetrieveEnvironmentInfo",
              "elasticloadbalancing:Describe*",
              "elastictranscoder:Read*",
              "elastictranscoder:List*",
              "iam:List*",
              "iam:Get*",
              "kinesis:Describe*",
              "kinesis:Get*",
              "kinesis:List*",
              "opsworks:Describe*",
              "opsworks:Get*",
              "route53:Get*",
              "route53:List*",
              "redshift:Describe*",
              "redshift:ViewQueriesInConsole",
              "rds:Describe*",
              "rds:ListTagsForResource",
              "s3:Get*",
              "s3:List*",
              "sdb:GetAttributes",
              "sdb:List*",
              "sdb:Select*",
              "ses:Get*",
              "ses:List*",
              "sns:Get*",
              "sns:List*",
              "sqs:GetQueueAttributes",
              "sqs:ListQueues",
              "sqs:ReceiveMessage",
              "storagegateway:List*",
              "storagegateway:Describe*",
              "trustedadvisor:Describe*"
            ],
            "Effect": "Allow",
            "Resource": "*"
          }, {
            "Effect": "Deny",
            "Action": "aws-portal:*Billing",
            "Resource": "*"
          }]

        },
        "Roles": [{
          "Ref": "rReadOnlyAdminRole"
        }],
        "Groups": [{
          "Ref": "rReadOnlyAdminGroup"
        }]
      }
    },

    "rReadOnlyBillingGroup": {
      "Type": "AWS::IAM::Group",
      "Properties": {
        "Path": "/"
      }
    },

    "rReadOnlyBillingPolicy": {
      "Type": "AWS::IAM::ManagedPolicy",
      "Properties": {
        "PolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [{
            "Effect": "Allow",
            "Action": "aws-portal:View*",
            "Resource": "*"
          }, {
            "Effect": "Deny",
            "Action": "aws-portal:*Account",
            "Resource": "*"
          }]
        },

        "Groups": [{
          "Ref": "rReadOnlyBillingGroup"
        }]
      }
    }

