                                        "ecr:BatchCheckLayerAvailability"
                                    ],
                                    "Resource": "*"
                                }
                            ]
                        }
                    }
                ]
            }
        },
        "AppRunner": {
            "Type": "AWS::AppRunner::Service",
            "Properties": {
                "ServiceName": {
                    "Fn::Join": [
                        "",
                        [
                            {
                                "Ref": "AWS::StackName"
                            },
                            "-service"
                        ]
                    ]
                },
                "SourceConfiguration": {
                    "AuthenticationConfiguration": {
                        "AccessRoleArn": {
                            "Fn::GetAtt": [
                                "AppRunnerRole",
                                "Arn"
