                                    ]
                                }
                            },
                            {
                                "Fn::ImportValue": {
                                    "Fn::Join": [
                                        ":",
                                        [
                                            {
                                                "Ref": "StackName"
                                            },
                                            "PrivateSubnetTwo"
                                        ]
                                    ]
                                }
                            }
                        ]
                    }
                },
                "TaskDefinition": {
                    "Ref": "TaskDefinition"
                },
                "LoadBalancers": [
                    {
                        "ContainerName": {
                            "Ref": "ServiceName"
                        },
