                            [
                                {
                                    "Ref": "StackName"
                                },
                                "VPCId"
                            ]
                        ]
                    }
                }
            }
        },
        "LoadBalancerRule": {
            "Type": "AWS::ElasticLoadBalancingV2::ListenerRule",
            "Properties": {
                "Actions": [
                    {
                        "TargetGroupArn": {
                            "Ref": "TargetGroup"
