            },
            "ValidationDomain": {
              "Ref": "BaseDomainName"
            }
          }
        ]
      }
    },
    "BackEndCertificate": {
      "Condition": "InUsEast1",
      "Type": "AWS::CertificateManager::Certificate",
      "Properties": {
        "DomainName": {
          "Fn::Sub": [
            "data.${Domain}",
            {
              "Domain": {
                "Ref": "BaseDomainName"
              }
            }
          ]
        },
        "DomainValidationOptions": [
          {
            "DomainName": {
              "Fn::Sub": [
                "data.${Domain}",
