        "MyCfnLifecyclePolicy": {
            "Type": "AWS::ImageBuilder::LifecyclePolicy",
            "Properties": {
                "ExecutionRole": {
                    "Fn::GetAtt": [
                        "MyIamRoleForLifeCyclePolicy3739591F",
                        "Arn"
                    ]
                },
                "Name": "sample-lifecycle-policy",
                "PolicyDetails": [
                    {
                        "Action": {
                            "IncludeResources": {
                                "Amis": true
                            },
                            "Type": "DEPRECATE"
                        },
                        "Filter": {
