AWSTemplateFormatVersion: "2010-09-09"
Description: Contains custom resource lambda which provides IOT Core Endpoint URL as output
Resources:
  #=======================================================
  #
  #                IOT Core Endpoint retrieval Lambda
  #
  #=======================================================
  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      Path: /
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service:
                - lambda.amazonaws.com
            Action:
              - sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Policies:
        - PolicyName:
            Fn::Sub: iot-core-endpoint-provider-policy-${AWS::Region}
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - iot:DescribeEndpoint
                Resource:
                  - "*"

  IotEndpointProvider:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: IotEndpointUrlProvider
      Handler: index.handler
      Runtime: nodejs24.x
      MemorySize: 128
      Timeout: 15
      Role:
        Fn::GetAtt:
          - LambdaExecutionRole
          - Arn
      TracingConfig:
        Mode: Active
      Code:
        ZipFile: |
          const { IoTClient, DescribeEndpointCommand } = require("@aws-sdk/client-iot");
          exports.handler = async function(event, context) {
              console.log("REQUEST RECEIVED:\n" + JSON.stringify(event));
              if (event.RequestType == "Delete") {
                  await sendResponse(event, context, "SUCCESS", {});
                  return;
              }
              const iot = new IoTClient();
              try {
                  const data = await iot.send(new DescribeEndpointCommand({endpointType: "iot:Data-ATS"}));
                  const responseData = { IotEndpointAddress: data.endpointAddress };
                  console.log('response data: ' + JSON.stringify(responseData));
                  await sendResponse(event, context, "SUCCESS", responseData);
              } catch (err) {
                  const responseData = { Error: "describeEndpoint call failed" };
                  console.log(responseData.Error + ":\n", err);
                  await sendResponse(event, context, "FAILED", responseData);
              }
          };
          // Send response to the pre-signed S3 URL; resolves once the PUT completes.
          function sendResponse(event, context, responseStatus, responseData) {
            return new Promise(function(resolve) {
              var responseBody = JSON.stringify({
                  Status: responseStatus,
                  Reason: "See the details in CloudWatch Log Stream: " + context.logStreamName,
                  PhysicalResourceId: context.logStreamName,
                  StackId: event.StackId,
                  RequestId: event.RequestId,
                  LogicalResourceId: event.LogicalResourceId,
                  Data: responseData
              });
              console.log("RESPONSE BODY:\n", responseBody);
              var https = require("https");
              var parsedUrl = new URL(event.ResponseURL);
              var options = {
                  hostname: parsedUrl.hostname,
                  port: 443,
                  path: parsedUrl.pathname + parsedUrl.search,
                  method: "PUT",
                  headers: {
                      "content-type": "",
                      "content-length": responseBody.length
                  }
              };
              console.log("SENDING RESPONSE...\n");
              var request = https.request(options, function(response) {
                  console.log("STATUS: " + response.statusCode);
                  console.log("HEADERS: " + JSON.stringify(response.headers));
                  resolve();
              });
              request.on("error", function(error) {
                  console.log("sendResponse Error:" + error);
                  resolve();
              });
              // write data to request body
              request.write(responseBody);
              request.end();
            });
          }
  IotEndpoint:
    Type: Custom::IotEndpoint
    Properties:
      ServiceToken:
        Fn::GetAtt:
          - IotEndpointProvider
          - Arn

Outputs:
  #=======================================================
  #
  #                 CloudFormation Outputs
  #
  #=======================================================
  IotEndpointAddress:
    Value:
      Fn::GetAtt:
        - IotEndpoint
        - IotEndpointAddress
    Description: Retrieved Iot Core Endpoint Url

AWSTemplateFormatVersion: "2010-09-09"
Description: Generates IOT Core policy for Device Onboarding
Resources:
  #=======================================================
  #
  #                    IOT Core Policy
  #
  #=======================================================

  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      Path: /
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service:
                - lambda.amazonaws.com
            Action:
              - sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Policies:
        - PolicyName:
            Fn::Sub: iot-core-policy-generator-policy-${AWS::Region}
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - iot:CreatePolicy
                Resource:
                  - "*"

  IotPolicyGenerator:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: IotPolicyGenerator
      Handler: index.handler
      Runtime: nodejs24.x
      MemorySize: 128
      Timeout: 15
      Role:
        Fn::GetAtt:
          - LambdaExecutionRole
          - Arn
      TracingConfig:
        Mode: Active
      Code:
        ZipFile: |
          const { IoTClient, CreatePolicyCommand } = require("@aws-sdk/client-iot");
          const response = require('cfn-response');
          exports.handler = async function(event, context) {
              console.log("REQUEST RECEIVED:\n" + JSON.stringify(event));
              if (event.RequestType == "Delete") {
                  await sendResponse(event, context, response.SUCCESS, {});
                  return;
              }
              const policyName = "device-onboarding";
              const region = process.env.AWS_REGION;
              const awsAccountId = context.invokedFunctionArn.split(':')[4];
              const policyDocument = `{
                  "Version": "2012-10-17",
                  "Statement": [
                  {
                      "Effect": "Allow",
                      "Action": [
                      "iot:Connect"
                      ],
                      "Resource": [
                      "arn:aws:iot:${region}:${awsAccountId}:client/\${iot:Connection.Thing.ThingName}"
                      ]
                  },
                  {
                      "Effect": "Allow",
                      "Action": [
                      "iot:Publish",
                      "iot:Receive"
                      ],
                      "Resource": [
                      "arn:aws:iot:${region}:${awsAccountId}:topic/\${iot:Connection.Thing.ThingName}/*"
                      ]
                  },
                  {
                      "Effect": "Allow",
                      "Action": [
                      "iot:Subscribe"
                      ],
                      "Resource": [
                      "arn:aws:iot:${region}:${awsAccountId}:topicfilter/\${iot:Connection.Thing.ThingName}/*"
                      ]
                  }
                  ]
              }`;
              console.log("Policy document:\n", policyDocument);
              const iot = new IoTClient();
              try {
                  const data = await iot.send(new CreatePolicyCommand({policyName, policyDocument}));
                  const responseData = { policyName: data.policyName };
                  console.log('Response data: ' + JSON.stringify(responseData));
                  await sendResponse(event, context, response.SUCCESS, responseData);
              } catch (err) {
                  const responseData = { Error: "createIoTPolicy call failed" };
                  console.error(responseData.Error + ":\n", err);
                  await sendResponse(event, context, response.FAILED, responseData);
              }
          };
          // Wrap cfn-response's callback-based send so it can be awaited in the async handler.
          function sendResponse(event, context, status, data) {
              return new Promise(function(resolve) {
                  const done = context.done;
                  context.done = function() {
                      resolve();
                      if (done) {
                          done.apply(context, arguments);
                      }
                  };
                  response.send(event, context, status, data);
              });
          }
  IoTPolicy:
    Type: Custom::IotPolicyGenerator
    Properties:
      ServiceToken:
        Fn::GetAtt:
          - IotPolicyGenerator
          - Arn

Outputs:
  #=======================================================
  #
  #                 CloudFormation Outputs
  #
  #=======================================================
  IOTCorePolicyName:
    Description: The name of the newly created IOT Core Policy
    Value:
      Fn::GetAtt:
        - IoTPolicy
        - policyName

AWSTemplateFormatVersion: '2010-09-09'
Description: CloudFormation template for X-Ray Transaction Search

Resources:
  LogsResourcePolicy:
    Type: AWS::Logs::ResourcePolicy
    Properties:
      PolicyName: TransactionSearchAccessPolicy
      PolicyDocument: !Sub |
        {
          "Version": "2012-10-17",
          "Statement": [
            {
              "Sid": "TransactionSearchXRayAccess",
              "Effect": "Allow",
              "Principal": {
                "Service": "xray.amazonaws.com"
              },
              "Action": "logs:PutLogEvents",
              "Resource": [
                "arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:aws/spans:*",
                "arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:/aws/application-signals/data:*"
              ],
              "Condition": {
                "ArnLike": {
                  "aws:SourceArn": "arn:${AWS::Partition}:xray:${AWS::Region}:${AWS::AccountId}:*"
                },
                "StringEquals": {
                  "aws:SourceAccount": "${AWS::AccountId}"
                }
              }
            }
          ]
        }

  XRayTransactionSearchConfig:
    Type: AWS::XRay::TransactionSearchConfig
    DependsOn: LogsResourcePolicy
    Properties:
      IndexingPercentage: 1

