{
  "AWSTemplateFormatVersion" : "2010-09-09",
  "Description" : "Qualys CSPM Read Only IAM Role",
  "Parameters" : {
    "QualysCSPMRoleName" : {
      "Type" : "String",
      "Description" : "Provide a role name (Example: QualysCSPMReadOnlyRole)",
      "Default" : "QualysCSPMReadOnlyRole"
    },
    "ExternalID" : {
      "Type" : "String",
      "Description" : "Provide an ExternalID",
      "Default" : "Qualys-USP3-Gems"
    }
  },
  "Resources" : {
    "QualysCSPMRole" : {
      "Type" : "AWS::IAM::Role",
      "Properties" : {
        "ManagedPolicyArns" : [ "arn:aws:iam::aws:policy/SecurityAudit" ],
        "AssumeRolePolicyDocument" : {
          "Version" : "2012-10-17",
          "Statement" : [ {
            "Effect" : "Allow",
            "Principal" : {
              "AWS" : "arn:aws:iam::123456789012:root"
            },
            "Action" : "sts:AssumeRole",
            "Condition" : {
              "StringEquals" : {
                "sts:ExternalId" : {
                  "Ref" : "ExternalID"
                }
              }
            }
          } ]
        },
        "RoleName" : {
          "Ref" : "QualysCSPMRoleName"
        }
      }
    },
    "CreateQualysCustomPolicy" : {
      "Type" : "AWS::IAM::ManagedPolicy",
      "Properties" : {
        "Description" : "This policy contains additional permissions for fetching resource details.",
        "ManagedPolicyName" : "QualysCSPMReadOnlyPolicy",
        "PolicyDocument" : {
          "Version" : "2012-10-17",
          "Statement" : [ {
            "Sid" : "QualysCustomPolicyPermissions",
            "Effect" : "Allow",
            "Action" : [ "states:DescribeStateMachine", "elasticfilesystem:DescribeFileSystemPolicy", "qldb:ListLedgers", "qldb:DescribeLedger", "kafka:ListClusters", "codebuild:BatchGetProjects", "wafv2:GetWebACLForResource", "backup:ListBackupVaults", "backup:DescribeBackupVault", "ec2:GetEbsEncryptionByDefault", "ec2:GetEbsDefaultKmsKeyId", "guardduty:ListDetectors", "guardduty:GetDetector", "glue:GetDataCatalogEncryptionSettings", "elasticmapreduce:GetBlockPublicAccessConfiguration", "lambda:GetFunctionConcurrency", "ds:ListLogSubscriptions", "ssm:getdocument", "ssm:getservicesetting", "states:GetExecutionHistory", "eks:ListFargateProfiles", "eks:DescribeFargateProfile", "states:Get*", "states:List*", "states:Describe*", "ssm:List*", "ssm:Describe*", "ssm:Get*", "appflow:DescribeFlow" ],
            "Resource" : "*"
          }, {
            "Sid" : "QualysAPIGatewayGetPermissions",
            "Effect" : "Allow",
            "Action" : "apigateway:GET",
            "Resource" : "arn:aws:apigateway:*::/restapis/*"
          } ]
        },
        "Roles" : [ {
          "Ref" : "QualysCSPMRole"
        } ]
      }
    }
  },
  "Outputs" : {
    "QualysCloudARN" : {
      "Value" : {
        "Fn::GetAtt" : [ "QualysCSPMRole", "Arn" ]
      },
      "Description" : "Role ARN to for CSPM Connector"
    }
  }
}

