      "Default":""
    },
    "Domain":{
      "Type":"String",
      "Description":"Route53 Hosted Zone name for prod IP (include trailing .)",
      "Default":""
    },
    "SubnetId":{
      "Type":"String",
      "Default":"",
      "Description":"TODO: Modify this later. VPC subnet id in which to place ENI"
    },
    "SecurityGroupId":{
      "Type":"String",
      "Description":"Security Group id with which to associate app ENI",
      "Default":""
    }
  },
  "Conditions":{
    "NoSecurityGroup":{
      "Fn::Equals":[
        {
          "Ref":"SecurityGroupId"
        },
        ""
      ]
    },
    "Route53Update":{
      "Fn::And":[
        {
          "Fn::Not":[
            {
              "Fn::Equals":[
                {
                  "Ref":"Hostname"
                },
                ""
              ]
            }
          ]
        },
        {
          "Fn::Not":[
            {
              "Fn::Equals":[
                {
                  "Ref":"Domain"
                },
                ""
              ]
            }
          ]
        }
      ]
    }
  },
  "Resources":{
    "EIP":{
      "Type":"AWS::EC2::EIP",
      "Properties":{
        "Domain":"vpc"
      }
    },
    "ProdDNSRecord":{
      "Type":"AWS::Route53::RecordSet",
      "Condition":"Route53Update",
      "Properties":{
        "HostedZoneName":{
          "Ref":"Domain"
        },
        "Comment":"DNS name for Dromedary prod.",
        "Name":{
          "Fn::Join":[
            "",
            [
              {
                "Ref":"Hostname"
              },
              ".",
              {
                "Ref":"Domain"
              }
            ]
          ]
        },
        "Type":"A",
        "TTL":"120",
        "ResourceRecords":[
          {
            "Ref":"EIP"
          }
        ]
      }
    },
    "ENI":{
      "Type":"AWS::EC2::NetworkInterface",
      "Properties":{
        "Description":"Dromedary Prod ENI",
        "SubnetId":{
          "Ref":"SubnetId"
        },
        "GroupSet":{
          "Fn::If":[
            "NoSecurityGroup",
            {
              "Ref":"AWS::NoValue"
            },
            [
              {
                "Ref":"SecurityGroupId"
              }
            ]
          ]
        },
        "Tags":[
          {
            "Key":"Application",
            "Value":{
              "Ref":"AWS::StackId"
            }
          },
          {
            "Key":"Name",
            "Value":{
              "Ref":"AWS::StackName"
            }
          }
        ]
      }
    },
    "EipAssocation":{
      "Type":"AWS::EC2::EIPAssociation",
      "Properties":{
        "AllocationId":{
          "Fn::GetAtt":[
            "EIP",
            "AllocationId"
          ]
        },
        "NetworkInterfaceId":{
          "Ref":"ENI"
        }
      }
    }
  },
  "Outputs":{
    "StackName":{
      "Value":{
        "Ref":"AWS::StackName"
      }
    },
    "PublicIp":{
      "Description":"Public IP Address of ENI",
      "Value":{
        "Ref":"EIP"
      }
    },
    "EniId":{
      "Description":"Elastic Network Interface Id",
      "Value":{
        "Ref":"ENI"
      }
