        },
        "AutoDeploy": true,
        "StageName": "prod"
      },
      "Type": "AWS::ApiGatewayV2::Stage"
    },
    "RestApiIfIntrinsicAndNoSwaggerEditor": {
      "Properties": {
        "Body": {
          "Fn::If": [
