              "action": "aws:runCommand",
              "name": "RunShellScript",
              "inputs": {
                "DocumentType": "Shell",
                "parameters": {
                  "commands": [
                    "echo Hello, World!"
                  ]
                }
              }
            }
          ]
        }
      }
    }
  },
  "Outputs": {
    "RoleArn": {
