{
  "AWSTemplateFormatVersion": "2010-09-09",

  "Description": "platform IAM 1.0.0 - Author Chris Morann",

  "Parameters": {
    "CfnBucketName": {
      "Type": "String",
      "Default": "platform"
    }
  },

  "Resources": {
    "InstanceRole":{
      "Type":"AWS::IAM::Role",
      "Properties":{
        "AssumeRolePolicyDocument":{
          "Statement":[
          {
            "Effect":"Allow",
            "Principal":{
              "Service":[
              "ec2.amazonaws.com"
              ]
            },
            "Action":[
              "sts:AssumeRole"
            ]
          }
          ]
        },
        "Path":"/"
      }
    },

    "RolePolicies":{
        "Type":"AWS::IAM::Policy",
        "Properties":{
          "PolicyName":"S3Download",
          "PolicyDocument":{
            "Statement":[
            {
              "Action":[
                "s3:ListBucket",
                "s3:GetBucketLocation",
                "s3:GetObject"
              ],
              "Effect":"Allow",
              "Resource": [
              {
                "Fn::Join": [ "", [
                "arn:aws:s3:::",
                "cfnstore"
                ] ]
            },

            {
              "Fn::Join": [ "", [
                "arn:aws:s3:::",
                "cfnstore/",
                { "Ref": "CfnBucketName"},
                "/*"
              ] ]
            }

          ]
            }
            ]
        },
        "Roles":[
          { "Ref":"InstanceRole" }
        ]
         }
      },

    "BucketProfile" : {
      "Type": "AWS::IAM::InstanceProfile",
        "Properties": {
          "Path": "/",
          "Roles": [
            { "Ref":  "InstanceRole"}
            ]
          }
      }
  },

  "Outputs": {
    "BucketProfile": {
      "Value": { "Ref": "BucketProfile"}
    },

    "InstanceRole": {
      "Value": { "Ref": "InstanceRole"}
    }
  }
}

