          "Statement": [
            {
              "Effect": "Allow",
              "Action": [
                "s3:GetObject",
                "s3:RestoreObject"
              ],
              "Resource": [
                "arn:aws:s3:::${aws:username}",
                "arn:aws:s3:::${aws:username}/*",
                "arn:aws:s3:::${aws:username}-*",
                "arn:aws:s3:::${aws:username}-*/*",
                "arn:aws:s3:::shared-*",
                "arn:aws:s3:::shared-*/*"
              ],
              "Condition" : {
                "Bool": {"aws:SecureTransport":"true"}
              }
            }
          ]
        },
        "Groups" : [{ "Ref" : "S3ReadGroup" }]
      }
    },

    "S3WriteGroup" : {
      "Type" : "AWS::IAM::Group"
    },
    "S3WriteGroupPolicies" : {
      "Type" : "AWS::IAM::Policy",
      "Properties" : {
        "PolicyName" : "s3-write",
        "PolicyDocument" : {
          "Version" : "2012-10-17",
          "Statement": [
            {
              "Effect": "Allow",
              "Action": [
                "s3:PutObject",
                "s3:AbortMultipartUpload"
              ],
              "Resource": [
                "arn:aws:s3:::${aws:username}",
                "arn:aws:s3:::${aws:username}/*",
                "arn:aws:s3:::${aws:username}",
                "arn:aws:s3:::${aws:username}-*/*",
                "arn:aws:s3:::shared-*",
                "arn:aws:s3:::shared-*/*"
              ],
