    }
  },

  "Resources": {
    "InstanceRole":{
      "Type":"AWS::IAM::Role",
      "Properties":{
        "AssumeRolePolicyDocument":{
          "Statement":[
          {
            "Effect":"Allow",
            "Principal":{
              "Service":[
              "ec2.amazonaws.com"
              ]
            },
            "Action":[
              "sts:AssumeRole"
            ]
          }
          ]
        },
        "Path":"/"
      }
    },

    "RolePolicies":{
        "Type":"AWS::IAM::Policy",
        "Properties":{
          "PolicyName":"S3Download",
          "PolicyDocument":{
            "Statement":[
            {
              "Action":[
                "s3:ListBucket",
                "s3:GetBucketLocation",
                "s3:GetObject"
              ],
              "Effect":"Allow",
              "Resource": [
              {
                "Fn::Join": [ "", [
                "arn:aws:s3:::",
                "cfnstore"
                ] ]
            },

