              "Fn::Join": [ "", [
                "arn:aws:s3:::",
                "cfnstore/",
                { "Ref": "CfnBucketName"},
                "/*"
              ] ]
            }

          ]
            }
            ]
        },
        "Roles":[
          { "Ref":"InstanceRole" }
        ]
         }
      },

