AWSTemplateFormatVersion: "2010-09-09"
Transform: AWS::Serverless-2016-10-31

Description: >
  Infrastructure as code for authorization layer (Amazon Verified Permissions and Cedar policies).

Resources:

  PolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      Description: Final version of the Cedar policy store that will be recreated independently.
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "actions": {
                "View": {
                  "appliesTo": {
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "required": true,
                          "name": "region",
                          "type": "String"
                        }
                      }
                    },
                    "principalTypes": [
                      "User"
                    ]
                  },
                  "memberOf": []
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "required": true,
                          "type": "String",
                          "name": "region"
                        }
                      }
                    },
                    "resourceTypes": [
                      "Book"
                    ]
                  },
                  "memberOf": []
                }
              },
              "entityTypes": {
                "Role": {
                  "memberOfTypes": [],
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "memberOfTypes": [
                    "Role"
                  ],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long",
                        "required": false
                      }
                    }
                  }
                },
                "Book": {
                  "memberOfTypes": [],
                  "shape": {
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "required": true,
                        "name": "User"
                      }
                    },
                    "type": "Record"
                  }
                }
              }
            }
          }

  PolicyStoreIdSSM:
    Type: AWS::SSM::Parameter
    Properties:
      Type: String
      Name: /bookstore-demo-app-with-authz/authorization/policy-store-id
      Value: !Ref PolicyStore

  RbacAdminStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows admins to list all books"
          Statement: |
            permit (
              principal in Bookstore::Role::"Admin",
              action in [ Bookstore::Action::"View" ],
              resource
            );

  RbacAdminForbidStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Denies admin Frank to list all books"
          Statement: |
            forbid (
              principal == Bookstore::User::"Frank",
              action in [ Bookstore::Action::"View" ],
              resource
            );

  RbacResourceOwnerStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows publishers to list books they have published"
          Statement: |
            permit (
              principal in Bookstore::Role::"Publisher",
              action in [ Bookstore::Action::"View" ],
              resource
            )
            when {
              principal == resource.owner
            };

  RbacExplicitStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows specific Publisher to list a specific book"
          Statement: |
            permit (
              principal == Bookstore::User::"Dante",
              action in [ Bookstore::Action::"View" ],
              resource == Bookstore::Book::"em1oadaa-b22k-4ea8-kk33-f6m217604o3m"
            );

  PermitAbacStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows customers with specific value for yearsAsMember attribute to list premium offers"
          Statement: |
            permit (
              principal in Bookstore::Role::"Customer",
              action in [ Bookstore::Action::"ViewWithPremiumOffers" ],
              resource
            )
            when { principal has yearsAsMember && principal.yearsAsMember >= 2 };

  DenyAbacStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Denies customers with specific value for yearsAsMember attribute to list premium offers"
          Statement: |
            forbid (
              principal in Bookstore::Role::"Customer",
              action in [ Bookstore::Action::"ViewWithPremiumOffers" ],
              resource
            )
            when { principal has yearsAsMember && principal.yearsAsMember < 2 };

  ContextStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Denies access for users outside the US region"
          Statement: |
            forbid (
              principal,
              action in [ Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers" ],
              resource
            )
            when { context.region != "US" };

Outputs:

  PolicyStoreId:
    Description: "Identifier of the Amazon Verified Permissions policy store."
    Value: !Ref PolicyStore

AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Codex on Bedrock — CloudWatch dashboard. Each widget is a native PromQL chart
  widget that queries the CloudWatch OTLP Prometheus-compatible API. The four
  Overview scorecards show rolling 24-hour totals via sum_over_time(...[1d]).

Parameters:
  DashboardName:
    Type: String
    Default: CodexOnBedrock
    Description: Name of the CloudWatch dashboard.

  MetricsRegion:
    Type: String
    Default: us-east-1
    Description: Region where OTLP metrics are ingested (sidecar sigv4auth region).

Resources:
  Dashboard:
    Type: AWS::CloudWatch::Dashboard
    Properties:
      DashboardName: !Ref DashboardName
      DashboardBody: !Sub |
        {
          "widgets": [
            {"type":"text","x":0,"y":0,"width":24,"height":1,"properties":{"markdown":"# Overview — rolling 24h totals"}},
            {
              "type":"chart","x":0,"y":1,"width":6,"height":3,
              "properties":{
                "title":"Total Tokens","region":"${MetricsRegion}","view":"number",
                "data":{"queries":[{"id":"a","type":"cloudwatch-metrics","language":"PromQL","step":60,
                  "query":"sum(histogram_sum(sum_over_time({\"codex.turn.token_usage\", token_type!=\"total\", \"@instrumentation.@name\"=\"codex\"}[1d])))"}]},
                "plotOptions":{"legend":{"position":"bottom","show":false},"xAxis":{"type":"datetime"},"yAxis":[{"type":"linear"}],
                  "style":{"lineOptions":{"filled":false,"stacked":false,"width":2,"pattern":"solid","spline":false},
                    "numberOptions":{"sparkline":true},"pieOptions":{"innerSize":"50%"},"barOptions":{},"gaugeOptions":{}}}
              }
            },
            {
              "type":"chart","x":6,"y":1,"width":6,"height":3,
              "properties":{
                "title":"Active Users","region":"${MetricsRegion}","view":"number",
                "data":{"queries":[{"id":"a","type":"cloudwatch-metrics","language":"PromQL","step":60,
                  "query":"count(group by (\"@resource.user.id\")(count_over_time({\"codex.turn.token_usage\", \"@instrumentation.@name\"=\"codex\"}[1d])))"}]},
                "plotOptions":{"legend":{"position":"bottom","show":false},"xAxis":{"type":"datetime"},"yAxis":[{"type":"linear"}],
                  "style":{"lineOptions":{"filled":false,"stacked":false,"width":2,"pattern":"solid","spline":false},
                    "numberOptions":{"sparkline":true},"pieOptions":{"innerSize":"50%"},"barOptions":{},"gaugeOptions":{}}}
              }
            },
            {
              "type":"chart","x":12,"y":1,"width":6,"height":3,
              "properties":{
                "title":"Total Turns","region":"${MetricsRegion}","view":"number",
                "data":{"queries":[{"id":"a","type":"cloudwatch-metrics","language":"PromQL","step":60,
                  "query":"sum(sum_over_time({\"codex.conversation.turn.count\", \"@instrumentation.@name\"=\"codex\"}[1d]))"}]},
                "plotOptions":{"legend":{"position":"bottom","show":false},"xAxis":{"type":"datetime"},"yAxis":[{"type":"linear"}],
                  "style":{"lineOptions":{"filled":false,"stacked":false,"width":2,"pattern":"solid","spline":false},
                    "numberOptions":{"sparkline":true},"pieOptions":{"innerSize":"50%"},"barOptions":{},"gaugeOptions":{}}}
              }
            },
            {
              "type":"chart","x":18,"y":1,"width":6,"height":3,
              "properties":{
                "title":"API Requests","region":"${MetricsRegion}","view":"number",
                "data":{"queries":[{"id":"a","type":"cloudwatch-metrics","language":"PromQL","step":60,
                  "query":"sum(sum_over_time({\"codex.api_request\", \"@instrumentation.@name\"=\"codex\"}[1d]))"}]},
                "plotOptions":{"legend":{"position":"bottom","show":false},"xAxis":{"type":"datetime"},"yAxis":[{"type":"linear"}],
                  "style":{"lineOptions":{"filled":false,"stacked":false,"width":2,"pattern":"solid","spline":false},
                    "numberOptions":{"sparkline":true},"pieOptions":{"innerSize":"50%"},"barOptions":{},"gaugeOptions":{}}}
              }
            },
            {"type":"text","x":0,"y":4,"width":24,"height":1,"properties":{"markdown":"# Token Usage"}},
            {
              "type":"chart","x":0,"y":5,"width":12,"height":6,
              "properties":{
                "title":"Tokens by type","region":"${MetricsRegion}","view":"line",
                "data":{"queries":[{"id":"a","type":"cloudwatch-metrics","language":"PromQL","step":60,
                  "query":"sum by (token_type)(histogram_sum({\"codex.turn.token_usage\", token_type!=\"total\", \"@instrumentation.@name\"=\"codex\"}))"}]},
                "plotOptions":{"legend":{"position":"bottom","show":true},"xAxis":{"type":"datetime"},"yAxis":[{"type":"linear"}],
                  "style":{"lineOptions":{"filled":true,"stacked":true,"width":2,"pattern":"solid","spline":false},
                    "numberOptions":{"sparkline":true},"pieOptions":{"innerSize":"50%"},"barOptions":{},"gaugeOptions":{}}}
              }
            },
            {
              "type":"chart","x":12,"y":5,"width":12,"height":6,
              "properties":{
                "title":"Tokens by model","region":"${MetricsRegion}","view":"line",
                "data":{"queries":[{"id":"a","type":"cloudwatch-metrics","language":"PromQL","step":60,
                  "query":"topk(10, sum by (model)(histogram_sum({\"codex.turn.token_usage\", token_type!=\"total\", \"@instrumentation.@name\"=\"codex\"})))"}]},
                "plotOptions":{"legend":{"position":"bottom","show":true},"xAxis":{"type":"datetime"},"yAxis":[{"type":"linear"}],
                  "style":{"lineOptions":{"filled":true,"stacked":true,"width":2,"pattern":"solid","spline":false},
                    "numberOptions":{"sparkline":true},"pieOptions":{"innerSize":"50%"},"barOptions":{},"gaugeOptions":{}}}
              }
            },

            {"type":"text","x":0,"y":11,"width":24,"height":1,"properties":{"markdown":"# Per-User Attribution"}},
            {
              "type":"chart","x":0,"y":12,"width":12,"height":6,
              "properties":{
                "title":"Top users by tokens","region":"${MetricsRegion}","view":"line",
                "data":{"queries":[{"id":"a","type":"cloudwatch-metrics","language":"PromQL","step":60,
                  "query":"topk(25, sum by (\"@resource.user.id\")(histogram_sum({\"codex.turn.token_usage\", token_type!=\"total\", \"@instrumentation.@name\"=\"codex\"})))"}]},
                "plotOptions":{"legend":{"position":"bottom","show":true},"xAxis":{"type":"datetime"},"yAxis":[{"type":"linear"}],
                  "style":{"lineOptions":{"filled":false,"stacked":false,"width":2,"pattern":"solid","spline":false},
                    "numberOptions":{"sparkline":true},"pieOptions":{"innerSize":"50%"},"barOptions":{},"gaugeOptions":{}}}
              }
            },
            {
              "type":"chart","x":12,"y":12,"width":12,"height":6,
              "properties":{
                "title":"Top users by API requests","region":"${MetricsRegion}","view":"line",
                "data":{"queries":[{"id":"a","type":"cloudwatch-metrics","language":"PromQL","step":60,
                  "query":"topk(25, sum by (\"@resource.user.id\")({\"codex.api_request\", \"@instrumentation.@name\"=\"codex\"}))"}]},
                "plotOptions":{"legend":{"position":"bottom","show":true},"xAxis":{"type":"datetime"},"yAxis":[{"type":"linear"}],
                  "style":{"lineOptions":{"filled":false,"stacked":false,"width":2,"pattern":"solid","spline":false},
                    "numberOptions":{"sparkline":true},"pieOptions":{"innerSize":"50%"},"barOptions":{},"gaugeOptions":{}}}
              }
            },

            {"type":"text","x":0,"y":18,"width":24,"height":1,"properties":{"markdown":"# Organizational Attribution"}},
            {
              "type":"chart","x":0,"y":19,"width":12,"height":6,
              "properties":{
                "title":"Tokens by department","region":"${MetricsRegion}","view":"line",
                "data":{"queries":[{"id":"a","type":"cloudwatch-metrics","language":"PromQL","step":60,
                  "query":"topk(25, sum by (\"@resource.department\")(histogram_sum({\"codex.turn.token_usage\", token_type!=\"total\", \"@instrumentation.@name\"=\"codex\"})))"}]},
                "plotOptions":{"legend":{"position":"bottom","show":true},"xAxis":{"type":"datetime"},"yAxis":[{"type":"linear"}],
                  "style":{"lineOptions":{"filled":false,"stacked":false,"width":2,"pattern":"solid","spline":false},
                    "numberOptions":{"sparkline":true},"pieOptions":{"innerSize":"50%"},"barOptions":{},"gaugeOptions":{}}}
              }
            },
            {
              "type":"chart","x":12,"y":19,"width":12,"height":6,
              "properties":{
                "title":"Tokens by team","region":"${MetricsRegion}","view":"line",
                "data":{"queries":[{"id":"a","type":"cloudwatch-metrics","language":"PromQL","step":60,
                  "query":"topk(25, sum by (\"@resource.team.id\")(histogram_sum({\"codex.turn.token_usage\", token_type!=\"total\", \"@instrumentation.@name\"=\"codex\"})))"}]},
                "plotOptions":{"legend":{"position":"bottom","show":true},"xAxis":{"type":"datetime"},"yAxis":[{"type":"linear"}],
                  "style":{"lineOptions":{"filled":false,"stacked":false,"width":2,"pattern":"solid","spline":false},
                    "numberOptions":{"sparkline":true},"pieOptions":{"innerSize":"50%"},"barOptions":{},"gaugeOptions":{}}}
              }
            },
            {
              "type":"chart","x":0,"y":25,"width":12,"height":6,
              "properties":{
                "title":"Tokens by cost center","region":"${MetricsRegion}","view":"line",
                "data":{"queries":[{"id":"a","type":"cloudwatch-metrics","language":"PromQL","step":60,
                  "query":"topk(25, sum by (\"@resource.cost_center\")(histogram_sum({\"codex.turn.token_usage\", token_type!=\"total\", \"@instrumentation.@name\"=\"codex\"})))"}]},
                "plotOptions":{"legend":{"position":"bottom","show":true},"xAxis":{"type":"datetime"},"yAxis":[{"type":"linear"}],
                  "style":{"lineOptions":{"filled":false,"stacked":false,"width":2,"pattern":"solid","spline":false},
                    "numberOptions":{"sparkline":true},"pieOptions":{"innerSize":"50%"},"barOptions":{},"gaugeOptions":{}}}
              }
            },
            {
              "type":"chart","x":12,"y":25,"width":12,"height":6,
              "properties":{
                "title":"Tokens by organization","region":"${MetricsRegion}","view":"line",
                "data":{"queries":[{"id":"a","type":"cloudwatch-metrics","language":"PromQL","step":60,
                  "query":"topk(25, sum by (\"@resource.organization\")(histogram_sum({\"codex.turn.token_usage\", token_type!=\"total\", \"@instrumentation.@name\"=\"codex\"})))"}]},
                "plotOptions":{"legend":{"position":"bottom","show":true},"xAxis":{"type":"datetime"},"yAxis":[{"type":"linear"}],
                  "style":{"lineOptions":{"filled":false,"stacked":false,"width":2,"pattern":"solid","spline":false},
                    "numberOptions":{"sparkline":true},"pieOptions":{"innerSize":"50%"},"barOptions":{},"gaugeOptions":{}}}
              }
            },

            {"type":"text","x":0,"y":31,"width":24,"height":1,"properties":{"markdown":"# Activity"}},
            {
              "type":"chart","x":0,"y":32,"width":12,"height":6,
              "properties":{
                "title":"Top users by tool calls","region":"${MetricsRegion}","view":"line",
                "data":{"queries":[{"id":"a","type":"cloudwatch-metrics","language":"PromQL","step":60,
                  "query":"topk(25, sum by (\"@resource.user.id\")(histogram_count({\"codex.turn.tool.call\", \"@instrumentation.@name\"=\"codex\"})))"}]},
                "plotOptions":{"legend":{"position":"bottom","show":true},"xAxis":{"type":"datetime"},"yAxis":[{"type":"linear"}],
                  "style":{"lineOptions":{"filled":false,"stacked":false,"width":2,"pattern":"solid","spline":false},
