    "AWSTemplateFormatVersion": "2010-09-09",
    "Description": "This template creates a role and a user that can be used to deploy tasks to CloudReactor. It also creates a managed policy you can attach to existing roles or users.",
    "Outputs": {
        "CloudreactorDeployerPolicyARN": {
            "Description": "The ARN of the policy containing permissions required to deploy tasks to CloudReactor",
            "Value": {
                "Ref": "deployerPolicy"
            }
        },
        "CloudreactorDeployerRoleARN": {
            "Description": "The ARN of a role that can deploy tasks to CloudReactor",
            "Value": {
                "Fn::GetAtt": [
                    "deployerRole",
                    "Arn"
                ]
            }
        },
        "CloudreactorDeployerInstanceProfileARN": {
            "Description": "The ARN of an instance profile that can deploy tasks to CloudReactor. If you assign an EC2 instance this instance profile, it will be able to deploy to tasks to ECS.",
            "Value": {
                "Fn::GetAtt": [
                    "deployerInstanceProfile",
                    "Arn"
                ]
            }
        },
        "CloudreactorDeployerUserARN": {
            "Description": "The ARN of a user that can deploy tasks to CloudReactor",
            "Value": {
                "Fn::GetAtt": [
                    "deployerUser",
                    "Arn"
                ]
            }
        }
    },
    "Parameters": {
        "DeploymentEnvironment": {
            "Description": "The name of the deployment environment, e.g. 'staging' or 'production'. Must consist only of alphanumeric characters or dashes. May be blank if the deployer role is to be used for multiple environments.",
            "Default": "",
            "MinLength": "0",
            "MaxLength": "128",
            "AllowedPattern": "[a-zA-Z0-9\\-]*",
            "NoEcho": "false",
            "Type": "String"
        },
        "SecretsPathPrefix": {
            "Description": "A path prefix which can limit the secret values the deployer role can modify. Leave blank if no Secrets Manager access is required.",
            "AllowedPattern": "[a-zA-Z0-9_/+=.@-]*",
            "Default": "",
            "MinLength": "0",
            "MaxLength": "128",
            "NoEcho": "false",
            "Type": "String"
        },
        "RoleAssumerPatterns": {
            "Description": "A comma-separated list of patterns for AWS principals (user ARNs or other role ARNs) that may assume the deployer role. Leave blank if no other AWS principal should be allowed to assume the role. Each pattern may contain wildcard ('*') characters.",
            "AllowedPattern": "[a-zA-Z0-9:/_+=,.@*-]*",
            "Default": "",
            "NoEcho": "false",
            "Type": "CommaDelimitedList"
        },
        "S3PathPrefix": {
            "Description": "A path prefix which can limit the S3 resources deployer role can read and modify. It may contain wildcard characters, but not '*' at the end. Leave blank if no limitation on S3 access is required. Can be set to '*' to allow access to all S3 resources.",
            "AllowedPattern": "([a-zA-Z0-9!_./()?*-]*)",
            "MaxLength": 1024,
            "Default": "",
            "NoEcho": "false",
            "Type": "String"
        },
        "CloudWatchLogGroupPathPrefix": {
            "Description": "A path prefix which can limit the deployer to write to certain log groups in CloudWatch logs.",
            "Default": "",
            "MinLength": "0",
            "MaxLength": "512",
            "NoEcho": "false",
            "Type": "String"
        }
    },
    "Conditions": {
        "HasEnvSuffix": {
            "Fn::Not": [
                {
                    "Fn::Equals": [
                        {
                            "Ref": "DeploymentEnvironment"
                        },
                        ""
                    ]
                }
            ]
        },
        "HasSecretManagerAccess": {
            "Fn::Not": [
                {
                    "Fn::Equals": [
                        {
                            "Ref": "SecretsPathPrefix"
                        },
                        ""
                    ]
                }
            ]
        },
        "HasRoleAssumer": {
            "Fn::Not": [
                {
                    "Fn::Equals": [
                        {
                            "Fn::Join": [
                                "",
                                {
                                    "Ref": "RoleAssumerPatterns"
                                }
                            ]
                        },
                        ""
                    ]
                }
            ]
        },
        "HasAllS3PathsAccess": {
            "Fn::Equals": [
              {
                  "Ref": "S3PathPrefix"
              },
              "*"
            ]
        },
        "HasNoS3Access": {
            "Fn::Equals": [
                {
                    "Ref": "S3PathPrefix"
                },
                ""
            ]
        }
    },
    "Resources": {
        "deployerPolicy":  {
            "Type" : "AWS::IAM::ManagedPolicy",
            "Properties" : {
                "PolicyDocument" : {
                    "Statement": [
                         {
                            "Effect": {
                                "Fn::If": [
                                    "HasNoS3Access",
                                    "Deny",
                                    "Allow"
                                ]
                            },
                            "Action": [
                                "s3:PutObject",
                                "s3:ListBucket",
                                "s3:GetObject",
                                "s3:DeleteObject"
                            ],
                            "Resource": {
                                "Fn::If": [
                                    "HasNoS3Access",
                                    "arn:aws:s3:::/dummy/*",
                                    {
                                        "Fn::If": [
                                            "HasAllS3PathsAccess",
                                            "arn:aws:s3:::*",
                                            {
                                                "Fn::Join": [
                                                    "",
                                                    [
                                                        "arn:aws:s3::",
                                                        {
                                                            "Ref" : "S3PathPrefix"
                                                        },
                                                        "*"
                                                    ]
                                                ]
                                            }
                                        ]
                                    }
                                ]
                            }
                        },
                        {
                            "Effect": "Allow",
                            "Action": "codebuild:*",
                            "Resource": "*"
                        },
                        {
                            "Effect": "Allow",
                            "Action": "codestar-connections:*",
                            "Resource": "*"
                        },
                        {
                            "Effect": "Allow",
                            "Resource": {
                                "Fn::Join": [
                                    "",
                                    [
                                        "arn:aws:logs:",
                                        {
                                            "Ref": "AWS::Region"
                                        },
                                        ":",
                                        {
                                            "Ref" : "AWS::AccountId"
                                        },
                                        ":log-group:",
                                        {
                                            "Ref" : "CloudWatchLogGroupPathPrefix"
                                        },
                                        "*"
                                    ]
                                ]
                            },
                            "Action": [
                                "logs:CreateLogGroup",
                                "logs:CreateLogStream",
                                "logs:PutLogEvents"
                            ]
                        },
                        {
                            "Effect": "Allow",
                            "Action": [
                                "ecr:BatchCheckLayerAvailability",
                                "ecr:BatchDeleteImage",
                                "ecr:CompleteLayerUpload",
                                "ecr:CreateRepository",
                                "ecr:DeleteLifecyclePolicy",
                                "ecr:DeleteRepositories",
                                "ecr:DescribeImageScanFindings",
                                "ecr:DescribeRepositories",
                                "ecr:GetAuthorizationToken",
                                "ecr:GetDownloadUrlForLayer",
                                "ecr:GetRegistryScanningConfiguration",
                                "ecr:GetRepositoryPolicy",
                                "ecr:InitiateLayerUpload",
                                "ecr:ListImages",
                                "ecr:ListTagsForResource",
                                "ecr:PutImage",
                                "ecr:PutImageScanningConfiguration",
                                "ecr:PutImageTagMutability",
                                "ecr:PutLifecyclePolicy",
                                "ecr:PutRegistryScanningConfiguration",
                                "ecr:StartImageScan",
                                "ecr:TagResource",
                                "ecr:UntagResource",
                                "ecr:UploadLayerPart",
                                "ecs:RegisterTaskDefinition"
                            ],
                            "Resource": [
                                "*"
                            ]
                        },
                        {
                            "Effect": {
                                "Fn::If": [
                                    "HasSecretManagerAccess",
                                    "Allow",
                                    "Deny"
                                ]
                            },
                            "Action": [
                                "secretsmanager:CancelRotateSecret",
                                "secretsmanager:CreateSecret",
                                "secretsmanager:DeleteResourcePolicy",
                                "secretsmanager:DeleteSecret",
                                "secretsmanager:DescribeSecret",
                                "secretsmanager:GetRandomPassword",
                                "secretsmanager:GetResourcePolicy",
                                "secretsmanager:GetSecretValue",
                                "secretsmanager:ListSecretVersionIds",
                                "secretsmanager:PutResourcePolicy",
                                "secretsmanager:PutSecretValue",
                                "secretsmanager:RemoveRegionsFromReplication",
                                "secretsmanager:ReplicateSecretToRegions",
                                "secretsmanager:RestoreSecret",
                                "secretsmanager:RotateSecret",
                                "secretsmanager:StopReplicationToReplica",
                                "secretsmanager:TagResource",
                                "secretsmanager:UntagResource",
                                "secretsmanager:UpdateSecret",
                                "secretsmanager:UpdateSecretVersionStage",
                                "secretsmanager:ValidateResourcePolicy"
                            ],
                            "Resource": [
                                {
                                    "Fn::Join": [
                                        "",
                                        [
                                            "arn:aws:secretsmanager:",
                                            {
                                                "Ref": "AWS::Region"
                                            },
                                            ":",
                                            {
                                                "Ref" : "AWS::AccountId"
                                            },
                                            ":secret:",
                                            {
                                                "Ref": "SecretsPathPrefix"
                                            },
                                            "*"
                                        ]
                                    ]
                                }
                            ]
                        },
                        {
                            "Effect": "Allow",
                            "Action": [
                                "iam:GetRole",
                                "iam:PassRole"
                            ],
                            "Resource": [
                                {
                                    "Fn::Join": [
                                        "",
                                        [
                                            "arn:aws:iam::",
                                            {
                                                "Ref" : "AWS::AccountId"
                                            },
                                            ":role/*"
                                        ]
                                    ]
                                }
                            ]
                        }
                    ],
                    "Version": "2012-10-17"
                },
                "ManagedPolicyName": {
                    "Fn::If": [
                        "HasEnvSuffix",
                        {
                            "Fn::Join": [
                                "",
                                [
                                    "cloudreactorDeployerPolicy-",
                                    {
                                        "Ref": "DeploymentEnvironment"
                                    }
                                ]
                            ]

                        },
                        "cloudreactorDeployerPolicy"
                    ]
                },
                "Description": "A managed policy containing permissions needed to deploy tasks to CloudReactor"
            }
        },
        "deployerRole": {
            "Type": "AWS::IAM::Role",
            "Properties": {
                "Description": "A role that can deploy tasks to CloudReactor",
                "Path": "/",
                "AssumeRolePolicyDocument": {
                    "Version" : "2012-10-17",
                    "Statement": [
                        {
                            "Effect": "Allow",
                            "Principal": {
                                "Service": [
                                    "ec2.amazonaws.com",
                                    "codebuild.amazonaws.com",
                                    "codedeploy.amazonaws.com"
                                ]
                            },
                            "Action": [ "sts:AssumeRole" ]
                        },
                        {
                            "Effect": "Allow",
                            "Principal": {
                                "AWS": {
                                    "Fn::If": [
                                        "HasRoleAssumer",
                                        {
                                            "Ref": "RoleAssumerPatterns"
                                        },
                                        {
                                            "Fn::GetAtt": [
                                                "deployerUser",
                                                "Arn"
                                            ]
                                        }
                                    ]
                                }
                            },
                            "Action": "sts:AssumeRole"
                        },
                        {
                            "Effect": "Allow",
                            "Principal": {
                                "AWS": {
                                    "Fn::GetAtt": [
                                        "deployerUser",
                                        "Arn"
                                    ]
                                }
                            },
                            "Action": "sts:AssumeRole"
                        },
                        {
                            "Effect": "Allow",
                            "Principal": {
                                "Service": [
                                    "codebuild.amazonaws.com",
                                    "codepipeline.amazonaws.com"
                                ]
                            },
                            "Action": "sts:AssumeRole"
                        }
                    ]
                },
                "ManagedPolicyArns": [
                    {
                        "Ref": "deployerPolicy"
                    },
                    "arn:aws:iam::aws:policy/AWSCodeBuildDeveloperAccess"
                ],
                "Tags": [
                    {
                        "Key": "ManagedBy",
                        "Value": "CloudReactor"
                    }
                ]
            }
        },
        "deployerInstanceProfile": {
           "Type": "AWS::IAM::InstanceProfile",
           "Properties": {
              "Path": "/",
              "Roles": [
                  {
                      "Ref": "deployerRole"
                  }
              ]
           }
        },
        "deployerUser": {
            "Type" : "AWS::IAM::User",
            "Properties" : {
                "UserName": {
                    "Fn::If": [
                        "HasEnvSuffix",
                        {
                            "Fn::Join": [
                                "",
                                [
                                    "cloudreactor-deployer-",
                                    {
                                        "Ref": "DeploymentEnvironment"
                                    }
                                ]
                            ]

                        },
                        "cloudreactor-deployer"
                    ]
                },

                "ManagedPolicyArns": [
                    {
                        "Ref": "deployerPolicy"
                    },
                    "arn:aws:iam::aws:policy/AWSCodeBuildDeveloperAccess"
                ],
                "Tags": [
                    {
                        "Key": "ManagedBy",
                        "Value": "CloudReactor"
                    }
                ]
            }
        }
    }
}

{
  "AWSTemplateFormatVersion": "2010-09-09",
  "Description": "Auto Tag (Open Source by GorillaStack)",
  "Parameters": {
    "LambdaName": {
      "Description": "The name of the Lambda Function.",
      "Type": "String",
      "Default": "AutoTag",
      "AllowedValues":[
        "AutoTag",
        "AutoTagDev"
      ]
    },
    "CodeS3Bucket": {
      "Description": "The name of the code bucket in S3.",
      "Type": "String",
      "Default": "gorillastack-autotag-releases-ap-northeast-1"
    },
    "CodeS3Path": {
      "Description": "The path of the code zip file in the code bucket in S3.",
      "Type": "String",
      "Default": "autotag-0.5.3.zip"
    },
    "AutoTagDebugLogging": {
      "Description": "Enable/Disable Debug Logging for the Lambda Function for all processed CloudTrail events.",
      "Type": "String",
      "AllowedValues": [
        "Enabled",
        "Disabled"
      ],
      "Default": "Disabled"
    },
    "AutoTagDebugLoggingOnFailure": {
      "Description": "Enable/Disable Debug Logging when the Lambda Function has a failure.",
      "Type": "String",
      "AllowedValues": [
        "Enabled",
        "Disabled"
      ],
      "Default": "Enabled"
    },
    "AutoTagTagsCreateTime": {
      "Description": "Enable/Disable the \"CreateTime\" tagging for all resources.",
      "Type": "String",
      "AllowedValues": [
        "Enabled",
        "Disabled"
      ],
      "Default": "Enabled"
    },
    "AutoTagTagsInvokedBy": {
      "Description": "Enable/Disable the \"InvokedBy\" tagging for all resources.",
      "Type": "String",
      "AllowedValues": [
        "Enabled",
        "Disabled"
      ],
      "Default": "Enabled"
    },
    "LogRetentionInDays": {
      "Description": "Number of days to retain AutoTag logs.",
      "Type": "Number",
      "Default": 90
    },
    "CustomTags": {
      "Description": "Define custom tags in a JSON document.",
      "Type": "String",
      "Default": ""
    }
  },
  "Resources": {
    "AutoTagLambdaFunction": {
      "Type": "AWS::Lambda::Function",
      "Properties": {
        "Code": {
          "ZipFile": "exports.handler = async () => ({ statusCode: 200 });"
        },
        "Description": "Auto Tag (Open Source by GorillaStack)",
        "FunctionName": {
          "Fn::Sub": "${LambdaName}"
        },
        "Handler": "index.handler",
        "Role": {
          "Fn::GetAtt": [
            "AutoTagExecutionRole",
            "Arn"
          ]
        },
        "Runtime": "nodejs24.x",
        "Timeout": 120,
        "Environment": {
          "Variables": {
            "DEBUG_LOGGING_ON_FAILURE": {
              "Ref": "AutoTagDebugLoggingOnFailure"
            },
            "DEBUG_LOGGING": {
              "Ref": "AutoTagDebugLogging"
            },
            "CREATE_TIME": {
              "Ref": "AutoTagTagsCreateTime"
            },
            "INVOKED_BY": {
              "Ref": "AutoTagTagsInvokedBy"
            },
            "ROLE_NAME": {
              "Ref": "AutoTagMasterRole"
            },
            "CUSTOM_TAGS": {
              "Ref": "CustomTags"
            }
          }
        }
      }
    },
    "AutoTagLogGroup": {
      "Type": "AWS::Logs::LogGroup",
      "Properties": {
        "LogGroupName": {
          "Fn::Sub": "/aws/lambda/${AutoTagLambdaFunction}"
        },
        "RetentionInDays": {
          "Ref": "LogRetentionInDays"
        }
      }
    },
    "AutoTagLogsMetricFilterMaxMemoryUsed": {
      "Type": "AWS::Logs::MetricFilter",
      "DependsOn": [
        "AutoTagLogGroup"
      ],
      "Properties": {
        "FilterPattern": "[report_name=\"REPORT\", request_id_name=\"RequestId:\", request_id_value, duration_name=\"Duration:\", duration_value, duration_unit=\"ms\", billed_duration_name_1=\"Billed\", bill_duration_name_2=\"Duration:\", billed_duration_value, billed_duration_unit=\"ms\", memory_size_name_1=\"Memory\", memory_size_name_2=\"Size:\", memory_size_value, memory_size_unit=\"MB\", max_memory_used_name_1=\"Max\", max_memory_used_name_2=\"Memory\", max_memory_used_name_3=\"Used:\", max_memory_used_value, max_memory_used_unit=\"MB\"]",
        "LogGroupName": {
          "Fn::Sub": "/aws/lambda/${AutoTagLambdaFunction}"
        },
        "MetricTransformations": [
          {
            "MetricValue": "$max_memory_used_value",
            "MetricNamespace": {
              "Fn::Sub": "PGi/${AutoTagLambdaFunction}"
            },
            "MetricName": {
              "Fn::Sub": "${AutoTagLambdaFunction}-MemoryUsed"
            }
          }
        ]
      }
    },
    "AutoTagExecutionRole": {
      "Type": "AWS::IAM::Role",
      "Properties": {
        "RoleName": {
          "Fn::Sub": "${AWS::StackName}Lambda"
        },
        "AssumeRolePolicyDocument": {
          "Statement": [
            {
              "Effect": "Allow",
              "Principal": {
                "Service": [
                  "lambda.amazonaws.com"
                ]
              },
              "Action": [
                "sts:AssumeRole"
              ]
            }
          ]
        },
        "Path": "/gorillastack/autotag/execution/"
      }
    },
    "AutoTagExecutionPolicy": {
      "Type": "AWS::IAM::Policy",
      "Properties": {
        "PolicyName": {
          "Fn::Sub": "${AWS::StackName}ExecutionPolicy"
        },
        "Roles": [
          {
            "Ref": "AutoTagExecutionRole"
          }
        ],
        "PolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [
            {
              "Effect": "Allow",
              "Action": [
                "logs:CreateLogGroup",
                "logs:CreateLogStream",
                "logs:PutLogEvents"
              ],
              "Resource": "arn:aws:logs:*:*:*"
            },
            {
              "Effect": "Allow",
              "Action": [
                "sts:*"
              ],
              "Resource": [
                {
                  "Fn::Sub": "arn:aws:iam::*:role/gorillastack/autotag/master/${AWS::StackName}"
                }
              ]
            }
          ]
        }
      }
    },
    "AutoTagMasterRole": {
      "Type": "AWS::IAM::Role",
      "Properties": {
        "RoleName": {
          "Fn::Sub": "${AWS::StackName}"
        },
        "AssumeRolePolicyDocument": {
          "Statement": [
            {
              "Effect": "Allow",
              "Principal": {
                "AWS": {
                  "Fn::GetAtt": [
                    "AutoTagExecutionRole",
                    "Arn"
                  ]
                }
              },
              "Action": [
                "sts:AssumeRole"
              ]
            }
          ]
        },
        "Path": "/gorillastack/autotag/master/"
      }
    },
    "AutoTagMasterPolicy": {
      "Type": "AWS::IAM::Policy",
      "Properties": {
        "PolicyName": {
          "Fn::Sub": "${AWS::StackName}MasterPolicy"
        },
        "Roles": [
