{
    "AWSTemplateFormatVersion": "2010-09-09",
    "Description": "Sample Beanstalk environmment template",
    "Conditions": {
        "CreateNewBeanstalkApp": {
            "Fn::Equals": [
                {
                    "Ref": "ExistingBeanstalkApplicationName"
                },
                ""
            ]
        },
        "CreateNewBeanstalkEnv": {
            "Fn::Equals": [
                {
                    "Ref": "ExistingBlueEnvironmentName"
                },
                ""
            ]
        },
        "CreateSampleAppForBeanstalk": {
            "Fn::Equals": [
                {
                    "Ref": "AppPackageS3Bucket"
                },
                "elasticbeanstalk-samples"
            ]
        }
    },
    "Parameters": {
        "AppPackageS3Bucket": {
            "Default": "elasticbeanstalk-samples",
            "Description": "Provide the S3 bucket where the Application Package exists for creating a new Beanstalk environment. This parameter can be ignored if using an existing Environment.",
            "Type": "String"
        },
        "AppPackageS3key": {
            "Default": "php-sample.zip",
            "Description": "Provide the S3 bucket key with the zip file package name for creating a new Beanstalk environment. This parameter can be ignored if using an existing Environment",
            "Type": "String"
        },
        "ExistingBeanstalkApplicationName": {
            "Default": "",
            "Description": "OPTIONAL: Required if the parameter 'ExistingBlueEnvironmentName' is provided. Give the Name of the Existing Beantalk Application where the existing Beanstalk Environment is running. Leave in blank if you want to create a new Application",
            "Type": "String"
        },
        "ExistingBlueEnvironmentName": {
            "Default": "",
            "Description": "Name of the Existing Beanstalk Environment as Blue Environment. Leave it blank if you want to create a new Environment. Provide a value to this parameter for which you would like to utilize the cost efficient Blue-Green deployments by creating a temporary cloned environment for routing the live traffic when this environment is in the Deployment/Test lifecycle",
            "Type": "String"
        },
        "GreenEnvironmentName": {
            "Default": "GreenEnvironment",
            "Description": "Provide a Name for the Green Environment, which will be the clone of the Blue Environment where the traffic will be routed temporarily for the amount of time the Blue Environment is completed with the deployment and tested. After the successful deployment to Blue Environment, the traffic will be routed back to Blue and the Green Environment will be terminated",
            "Type": "String"
        },
        "NewBeanstalkApplicationName": {
            "Default": "BlueGreenBeanstalkApplication",
            "Description": "OPTIONAL:Provide a name for a new Beantalk Application where the new Blue Environment and the clone will be created. If not provided, the name will be 'BlueGreenBeanstalkApplication' by default. Value for this parameter is required only when you leave the 'ExistingBlueEnvironmentName' and 'ExistingBeanstalkApplicationName' property empty",
            "Type": "String"
        },
        "NewBlueEnvironmentName": {
            "Default": "BlueEnvironment",
            "Description": "Provide a name for creating a new Beanstalk Environment as Blue Environment that uses a Sample Application. This is the main environment from which a temporary clone called 'Green Environment' will be created to route the live traffic until the deployment is completed and tested with this one. Value for this parameter is required only when you leave the 'ExistingBlueEnvironmentName' property empty",
            "Type": "String"
        },
        "SolutionStackForNewBeanstalkEnv": {
            "Default": "64bit Amazon Linux 2023 v4.13.6 running PHP 8.3",
            "Description": "Provide a name for the Beanstalk Solution stack for launching the new Blue Environment. If not provided, the default will be a PHP solution stack. Please refer the following document https://docs.aws.amazon.com/elasticbeanstalk/latest/dg/concepts.platforms.html for all the solution stack values. Value for this parameter is required only when you leave the 'ExistingBlueEnvironmentName' property empty",
            "Type": "String"
        }
    },
    "Resources": {
        "BeanstalkAppVersion": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "ApplicationName": {
                    "Fn::If": [
                        "CreateNewBeanstalkApp",
                        {
                            "Ref": "BeanstalkApplication"
                        },
                        {
                            "Ref": "ExistingBeanstalkApplicationName"
                        }
                    ]
                },
                "Description": "my sample version",
                "SourceBundle": {
                    "S3Bucket": {
                        "Fn::If": [
                            "CreateSampleAppForBeanstalk",
                            {
                                "Fn::Join": [
                                    "",
                                    [
                                        {
                                            "Ref": "AppPackageS3Bucket"
                                        },
                                        "-",
                                        {
                                            "Ref": "AWS::Region"
                                        }
                                    ]
                                ]
                            },
                            {
                                "Ref": "AppPackageS3Bucket"
                            }
                        ]
                    },
                    "S3Key": {
                        "Ref": "AppPackageS3key"
                    }
                }
            },
            "Type": "AWS::ElasticBeanstalk::ApplicationVersion"
        },
        "BeanstalkApplication": {
            "Condition": "CreateNewBeanstalkApp",
            "Properties": {
                "ApplicationName": {
                    "Ref": "NewBeanstalkApplicationName"
                },
                "Description": "AWS Elastic Beanstalk PHP Sample Application"
            },
            "Type": "AWS::ElasticBeanstalk::Application"
        },
        "BeanstalkEnvironment": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "ApplicationName": {
                    "Fn::If": [
                        "CreateNewBeanstalkApp",
                        {
                            "Ref": "BeanstalkApplication"
                        },
                        {
                            "Ref": "ExistingBeanstalkApplicationName"
                        }
                    ]
                },
                "Description": "AWS Elastic Beanstalk Environment running PHP Sample Application",
                "EnvironmentName": {
                    "Ref": "NewBlueEnvironmentName"
                },
                "OptionSettings": [
                    {
                        "Namespace": "aws:autoscaling:launchconfiguration",
                        "OptionName": "IamInstanceProfile",
                        "Value": {
                            "Ref": "BeanstalkInstanceProfile"
                        }
                    },
                    {
                        "Namespace": "aws:elasticbeanstalk:environment",
                        "OptionName": "ServiceRole",
                        "Value": {
                            "Ref": "BeanstalkServiceRole"
                        }
                    }
                ],
                "SolutionStackName": {
                    "Ref": "SolutionStackForNewBeanstalkEnv"
                },
                "VersionLabel": {
                    "Ref": "BeanstalkAppVersion"
                }
            },
            "Type": "AWS::ElasticBeanstalk::Environment"
        },
        "BeanstalkInstanceProfile": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "Path": "/",
                "Roles": [
                    {
                        "Ref": "BeanstalkInstanceProfileRole"
                    }
                ]
            },
            "Type": "AWS::IAM::InstanceProfile"
        },
        "BeanstalkInstanceProfileRole": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "AssumeRolePolicyDocument": {
                    "Statement": [
                        {
                            "Action": [
                                "sts:AssumeRole"
                            ],
                            "Effect": "Allow",
                            "Principal": {
                                "Service": [
                                    "ec2.amazonaws.com"
                                ]
                            }
                        }
                    ],
                    "Version": "2012-10-17"
                },
                "Path": "/",
                "Policies": [
                    {
                        "PolicyDocument": {
                            "Statement": [
                                {
                                    "Action": [
                                        "s3:Get*",
                                        "s3:List*",
                                        "s3:PutObject"
                                    ],
                                    "Effect": "Allow",
                                    "Resource": [
                                        {
                                            "Fn::Join": [
                                                "",
                                                [
                                                    "arn:",
                                                    {
                                                        "Ref": "AWS::Partition"
                                                    },
                                                    ":s3:::elasticbeanstalk-*-",
                                                    {
                                                        "Ref": "AWS::AccountId"
                                                    }
                                                ]
                                            ]
                                        },
                                        {
                                            "Fn::Join": [
                                                "",
                                                [
                                                    "arn:",
                                                    {
                                                        "Ref": "AWS::Partition"
                                                    },
                                                    ":s3:::elasticbeanstalk-*-",
                                                    {
                                                        "Ref": "AWS::AccountId"
                                                    },
                                                    "/*"
                                                ]
                                            ]
                                        },
                                        {
                                            "Fn::Join": [
                                                "",
                                                [
                                                    "arn:",
                                                    {
                                                        "Ref": "AWS::Partition"
                                                    },
                                                    ":s3:::elasticbeanstalk-*-",
                                                    {
                                                        "Ref": "AWS::AccountId"
                                                    },
                                                    "-*"
                                                ]
                                            ]
                                        },
                                        {
                                            "Fn::Join": [
                                                "",
                                                [
                                                    "arn:",
                                                    {
                                                        "Ref": "AWS::Partition"
                                                    },
                                                    ":s3:::elasticbeanstalk-*-",
                                                    {
                                                        "Ref": "AWS::AccountId"
                                                    },
                                                    "-*/*"
                                                ]
                                            ]
                                        }
                                    ],
                                    "Sid": "BucketAccess"
                                },
                                {
                                    "Action": [
                                        "cloudwatch:PutMetricData"
                                    ],
                                    "Effect": "Allow",
                                    "Resource": "*",
                                    "Sid": "MetricsAccess"
                                },
                                {
                                    "Action": [
                                        "logs:PutLogEvents",
                                        "logs:CreateLogStream",
                                        "logs:DescribeLogStreams",
                                        "logs:DescribeLogGroups"
                                    ],
                                    "Effect": "Allow",
                                    "Resource": [
                                        "arn:aws:logs:*:*:log-group:/aws/elasticbeanstalk*"
                                    ],
                                    "Sid": "CloudWatchLogsAccess"
                                }
                            ],
                            "Version": "2012-10-17"
                        },
                        "PolicyName": "root"
                    }
                ]
            },
            "Type": "AWS::IAM::Role"
        },
        "BeanstalkServiceRole": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "AssumeRolePolicyDocument": {
                    "Statement": [
                        {
                            "Action": "sts:AssumeRole",
                            "Condition": {
                                "StringEquals": {
                                    "sts:ExternalId": "elasticbeanstalk"
                                }
                            },
                            "Effect": "Allow",
                            "Principal": {
                                "Service": "elasticbeanstalk.amazonaws.com"
                            },
                            "Sid": ""
                        }
                    ],
                    "Version": "2012-10-17"
                },
                "Path": "/",
                "Policies": [
                    {
                        "PolicyDocument": {
                            "Statement": [
                                {
                                    "Action": [
                                        "elasticloadbalancing:DescribeInstanceHealth",
                                        "ec2:DescribeInstances",
                                        "ec2:DescribeInstanceStatus",
                                        "ec2:GetConsoleOutput",
                                        "ec2:AssociateAddress",
                                        "ec2:DescribeAddresses",
                                        "ec2:DescribeSecurityGroups",
                                        "sqs:GetQueueAttributes",
                                        "sqs:GetQueueUrl",
                                        "autoscaling:DescribeAutoScalingGroups",
                                        "autoscaling:DescribeAutoScalingInstances",
                                        "autoscaling:DescribeScalingActivities",
                                        "autoscaling:DescribeNotificationConfigurations"
                                    ],
                                    "Effect": "Allow",
                                    "Resource": [
                                        "*"
                                    ]
                                }
                            ],
                            "Version": "2012-10-17"
                        },
                        "PolicyName": "root"
                    }
                ]
            },
            "Type": "AWS::IAM::Role"
        }
    },
    "Outputs": {
        "BeanstalkEnvironment": {
            "Value": {
                "Fn::If": [
                    "CreateNewBeanstalkEnv",
                    {
                        "Ref": "BeanstalkEnvironment"
                    },
                    ""
                ]
            }
        },
        "BeanstalkEnvEndPointUrl": {
            "Description": "New Beanstalk Environment Endpoint URL",
            "Value": {
                "Fn::If": [
                    "CreateNewBeanstalkEnv",
                    {
                        "Fn::GetAtt": [
                            "BeanstalkEnvironment",
                            "EndpointURL"
                        ]
                    },
                    ""
                ]
            }
        }
    }
}

AWSTemplateFormatVersion: "2010-09-09"
Transform: AWS::Serverless-2016-10-31

Description: >
  Infrastructure as code for authorization layer (Amazon Verified Permissions and Cedar policies).

Resources:

  PolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      Description: Final version of the Cedar policy store that will be recreated independently.
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "actions": {
                "View": {
                  "appliesTo": {
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "required": true,
                          "type": "String"
                        }
                      }
                    },
                    "principalTypes": [
                      "User"
                    ]
                  },
                  "memberOf": []
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "required": true,
                          "type": "String"
                        }
                      }
                    },
                    "resourceTypes": [
                      "Book"
                    ]
                  },
                  "memberOf": []
                }
              },
              "entityTypes": {
                "Role": {
                  "memberOfTypes": [],
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "memberOfTypes": [
                    "Role"
                  ],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long",
                        "required": false
                      }
                    }
                  }
                },
                "Book": {
                  "memberOfTypes": [],
                  "shape": {
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "required": true,
                        "name": "User"
                      }
                    },
                    "type": "Record"
                  }
                }
              }
            }
          }

  PolicyStoreIdSSM:
    Type: AWS::SSM::Parameter
    Properties:
      Type: String
      Name: /bookstore-demo-app-with-authz/authorization/policy-store-id
      Value: !Ref PolicyStore

  RbacAdminStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows admins to list all books"
          Statement: |
            permit (
              principal in Bookstore::Role::"Admin",
              action in [ Bookstore::Action::"View" ],
              resource
            );

  RbacAdminForbidStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Denies admin Frank to list all books"
          Statement: |
            forbid (
              principal == Bookstore::User::"Frank",
              action in [ Bookstore::Action::"View" ],
              resource
            );

  RbacResourceOwnerStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows publishers to list books they have published"
          Statement: |
            permit (
              principal in Bookstore::Role::"Publisher",
              action in [ Bookstore::Action::"View" ],
              resource
            )
            when {
              principal == resource.owner
            };

  RbacExplicitStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows specific Publisher to list a specific book"
          Statement: |
            permit (
              principal == Bookstore::User::"Dante",
              action in [ Bookstore::Action::"View" ],
              resource == Bookstore::Book::"em1oadaa-b22k-4ea8-kk33-f6m217604o3m"
            );

  PermitAbacStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows customers with specific value for yearsAsMember attribute to list premium offers"
          Statement: |
            permit (
              principal in Bookstore::Role::"Customer",
              action in [ Bookstore::Action::"ViewWithPremiumOffers" ],
              resource
            )
            when { principal has yearsAsMember && principal.yearsAsMember >= 2 };

  DenyAbacStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Denies customers with specific value for yearsAsMember attribute to list premium offers"
          Statement: |
            forbid (
              principal in Bookstore::Role::"Customer",
              action in [ Bookstore::Action::"ViewWithPremiumOffers" ],
              resource
            )
            when { principal has yearsAsMember && principal.yearsAsMember < 2 };

  ContextStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Denies access for users outside the US region"
          Statement: |
            forbid (
              principal,
              action in [ Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers" ],
              resource
            )
            when { context.region != "US" };

Outputs:

  PolicyStoreId:
    Description: "Identifier of the Amazon Verified Permissions policy store."
    Value: !Ref PolicyStore

