                                    ],
                                    "Sid": "CloudWatchLogsAccess"
                                }
                            ],
                            "Version": "2012-10-17"
                        },
                        "PolicyName": "root"
                    }
                ]
            },
            "Type": "AWS::IAM::Role"
        },
        "BeanstalkServiceRole": {
